// This file demonstrates how the automated component discovery works
// Run this in development to verify everything is working correctly

import { debugDiscoveredComponents } from './folderMapping';
import { debugDiscoveredDocs } from './registry';

/**
 * Test the automated component discovery system
 * This will log all discovered components and their metadata
 */
export function testAutoDiscovery() {
  console.log('🚀 Testing Automated Component Discovery System');
  console.log('=' .repeat(60));
  
  // Test component discovery
  const componentInfo = debugDiscoveredComponents();
  
  console.log('\n' + '=' .repeat(60));
  
  // Test documentation discovery
  const docsInfo = debugDiscoveredDocs();
  
  console.log('\n' + '=' .repeat(60));
  console.log('✅ Auto-discovery test completed!');
  console.log(`Found ${componentInfo.count} components and ${docsInfo.count} documentation files`);
  
  return {
    components: componentInfo,
    docs: docsInfo
  };
}

// Auto-run in development
if (import.meta.env.DEV) {
  testAutoDiscovery();
}
